use kmp::{build_failure, kmp_search};

#[test]
fn test_kmp_basic() {
    assert_eq!(kmp_search("abcabcabc", "abc"), vec![0usize, 3, 6]);
}

#[test]
fn test_kmp_no_match() {
    assert_eq!(kmp_search("hello", "world"), Vec::<usize>::new());
}

#[test]
fn test_kmp_single_char() {
    assert_eq!(kmp_search("aabaa", "a"), vec![0usize, 1, 3, 4]);
}

#[test]
fn test_kmp_empty_text() {
    assert_eq!(kmp_search("", "abc"), Vec::<usize>::new());
}

#[test]
fn test_kmp_overlapping() {
    assert_eq!(kmp_search("aaaa", "aa"), vec![0usize, 1, 2]);
}

